package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
/** Pure report/source contracts. No Android source, OCR, IPC or input is invoked. */
public class RootCurrentCardsWiringTest {
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n)).replace("\r\n","\n");}
 private String between(String s,String a,String b){return s.substring(s.indexOf(a),s.indexOf(b,s.indexOf(a)));}
 @Test public void allActiveCurrentClaimsUseNewNamespaceOnly()throws Exception{for(String n:new String[]{"CaptureSessionRuntime.java","DormantCaptureConfirmationActivity.java","VisibleCaptureAuthority.java","RootReturnReadIntent.java"}){String s=source(n);assertFalse(n,s.contains("RootCurrentReadScope"));assertTrue(n,s.contains("RootCurrentCardScope"));}assertNotEquals(RootCurrentReadScope.DIRECTORY,RootCurrentCardScope.DIRECTORY);assertEquals(3,RootCurrentCardScope.MAX_FRAMES);}
 @Test public void dedicatedHolderIsNotTheLegacyBusinessFrame()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("returnReadIntent.currentCardsOnly()?ReadOnlyTwoStageRun.Capture.moreCurrentCards("));assertTrue(r.contains(":ReadOnlyTwoStageRun.Capture.moreCurrentStatus("));String report=between(r,"static String qualifiedCurrentReadSummary(","static boolean visibleKnownSetComplete(");assertTrue(report.contains("observation.currentCards()"));assertTrue(report.indexOf("if(!healthy)")<report.indexOf("observation.currentCards()"));for(String bad:new String[]{"new NativeAutonomousCardRun","TapActor","BackActor",".cards()","configuredTarget","ReturnPermit"})assertFalse(bad,report.contains(bad));}
 @Test public void missingObservationNeverHasQualifiedStatus(){String s=CaptureSessionRuntime.qualifiedCurrentReadSummary(null,true,true);assertTrue(s.contains("currentStatusEvidence=UNQUALIFIED"));assertFalse(s.contains("currentStatusEvidence=QUALIFIED"));}
 @Test public void unhealthyResultDoesNotExposeEvenValidPerCardSemanticStatus(){var c=ReadOnlyTwoStageRun.Capture.moreCurrentCards(new Object(),"v34-report",523,1000,0,1000,()->false);var o=c.prepare(AutonomousCardFixture.pixels(false,false),523,1000,AutonomousCardFixture.rows(false,false),()->false);assertNotNull(o);String s=CaptureSessionRuntime.qualifiedCurrentReadSummary(o,false,true);assertTrue(s.contains("currentStatusEvidence=UNQUALIFIED"));assertFalse(s.contains("EXACT_A"));assertFalse(s.contains("EXACT_B"));assertFalse(s.contains("PENDING_5"));}
 @Test public void healthyCardsReportHasExplicitNoFamilyOrBusinessAuthority(){var c=ReadOnlyTwoStageRun.Capture.moreCurrentCards(new Object(),"v34-report",523,1000,0,1000,()->false);var o=c.prepare(AutonomousCardFixture.pixels(false,false),523,1000,AutonomousCardFixture.rows(false,false),()->false);assertNotNull(o);assertNotNull(o.currentCards());String s=CaptureSessionRuntime.qualifiedCurrentReadSummary(o,true,true);assertTrue(s.contains("currentStatusEvidence=QUALIFIED"));assertTrue(s.contains("independentCurrentCards=true completeFamily=false businessEligible=false"));assertFalse(s.contains(AutonomousCardFixture.A));assertFalse(s.contains(AutonomousCardFixture.B));assertTrue(s.length()<5000);}
 @Test public void nextStillRequiresOldExactHealthyUnpresentedPredicate()throws Exception{String r=source("CaptureSessionRuntime.java"),p=between(r,"static boolean returnReadUnpresented(","static String qualifiedCurrentReadSummary(");assertFalse(p.contains("currentCards()"));for(String token:new String[]{"headerCount()!=0","marker.candidates()!=0","RewardRegionLocator.Status.NO_CARDS","cv.cardTotal()==0","populationVariance()==0.0","band.flatCount()==band.count()"})assertTrue(token,p.contains(token));assertTrue(r.contains("unpresented=healthy&&returnReadUnpresented("));}
 @Test public void disclosureAndNoInputModeRemainExplicit()throws Exception{String u=source("RootCaptureUi.java");assertTrue(u.contains("v34：独立当前页逐卡只读"));assertTrue(u.contains("02:25 至 03:30"));assertTrue(u.contains("UNMODELED"));assertTrue(u.contains("空正文的匿名完成卡不命名为A"));assertTrue(u.contains("零Back、零任务点击"));String r=between(source("CaptureSessionRuntime.java"),"private void currentBeforeReadOnOwner()","private void returnBeforeReadOnOwner()");assertFalse(r.contains("new RootReturnReadController"));assertFalse(r.contains("BackActor"));assertTrue(r.contains("readCurrentTemplate(shape)"));}
 @Test public void unchangedLegacyHolderStillUsesLegacyReport(){var o=CurrentFamilyStatusTest.observe(false,false);String s=CaptureSessionRuntime.qualifiedCurrentReadSummary(o,true,false);assertEquals("currentStatusEvidence=QUALIFIED "+o.currentStatusSummary(),s);assertFalse(s.contains("independentCurrentCards=true"));}
}
